// ============================================================
// BRANCH 1: Find duplicate records by company_name
// Output one item per record to delete, each with a deleteUrl
// ============================================================
const response = $input.first().json;
const records = response.records || [];

const groups = {};
for (const rec of records) {
  const name = (rec.fields.company_name || '').toLowerCase().trim();
  if (!name) continue;
  if (!groups[name]) groups[name] = [];
  groups[name].push({
    id: rec.id,
    company_name: rec.fields.company_name,
    createdTime: rec.createdTime || ''
  });
}

const toDelete = [];
for (const [name, recs] of Object.entries(groups)) {
  if (recs.length <= 1) continue;
  // Sort by createdTime descending (newest first)
  recs.sort((a, b) => (b.createdTime || '').localeCompare(a.createdTime || ''));
  // Keep newest, delete the rest
  for (let i = 1; i < recs.length; i++) {
    toDelete.push({
      json: {
        recordId: recs[i].id,
        company_name: recs[i].company_name,
        kept_id: recs[0].id,
        deleteUrl: `https://api.airtable.com/v0/appvFxwZc9yU8o8pK/tbl6qih4ODd7qKFZ1/${recs[i].id}`
      }
    });
  }
}

if (toDelete.length === 0) {
  return [{ json: { _noDuplicates: true, message: 'No duplicates found' } }];
}

return toDelete;

// ============================================================
// BRANCH 2: Build batch update payload to fix source field
// Read notes to determine the correct source value
// Output batch PATCH body for Airtable
// ============================================================
const response = $input.first().json;
const records = response.records || [];

const updates = [];
for (const rec of records) {
  const currentSource = (rec.fields.source || '').toLowerCase().trim();
  // Only fix records that have 'unknown' or empty source
  if (currentSource && currentSource !== 'unknown') continue;

  const notes = (rec.fields.notes || '').toLowerCase();
  let newSource = '';

  if (notes.includes('prospect finder') || (notes.includes('auto-discovered') && notes.includes('ugc score'))) {
    newSource = 'prospect_finder';
  } else if (notes.includes('ad library scanner') || notes.includes('meta ads without ugc')) {
    newSource = 'ad_library_scanner';
  } else if (notes.includes('discovery signal') || notes.includes('best service')) {
    newSource = 'prospect_finder';
  }

  if (newSource) {
    updates.push({ id: rec.id, fields: { source: newSource } });
  }
}

if (updates.length === 0) {
  return [{ json: { _noUpdates: true, message: 'No source fields to fix' } }];
}

// Split into batches of 10 (Airtable max per PATCH request)
const batches = [];
for (let i = 0; i < updates.length; i += 10) {
  batches.push({
    json: {
      batchBody: JSON.stringify({ records: updates.slice(i, i + 10) }),
      batchIndex: Math.floor(i / 10) + 1,
      batchCount: updates.slice(i, i + 10).length
    }
  });
}

return batches;
